            $skillsContainer.append($skillsList);
        }

        /* NPC Status */
        const npcNames = _.get(data, 'NPC姓名', {});
        const npcStates = _.get(data, 'NPC状态', {});
        const $npcContainer = $('#npc-container');
        $npcContainer.empty();
        let hasNpcs = false;

        for (const npcKey of ['NPC_1', 'NPC_2', 'NPC_3']) {
