      /* Toggles a section's visibility */
      function toggleSection($header) {
        const $content = $header.next('.section-content');
        $content.toggleClass('expanded');
        $header.find('.arrow').css('transform', $content.hasClass('expanded') ? 'rotate(90deg)' : 'rotate(0deg)');
      }

      /* Initializes theme switching functionality */
      function initThemeSwitcher() {
        const $body = $('body');
        // 更新为新的主题名称
        const themes = ['cherry', 'mint', 'sky', 'gold'];
        const savedTheme = localStorage.getItem('axiomatic_web_theme_v2') || 'cherry';

        function setTheme(theme) {
            $body.removeClass(themes.map(t => `theme-${t}`).join(' '));
            // 默认是cherry，所以如果不是cherry才添加class
            if (theme !== 'cherry') {
                $body.addClass(`theme-${theme}`);
            }
            $('.theme-btn').removeClass('active');
            $(`.theme-btn.${theme}`).addClass('active');
            localStorage.setItem('axiomatic_web_theme_v2', theme);
        }

        $('.theme-btn').on('click', function() {
            setTheme($(this).data('theme'));
        });

        setTheme(savedTheme);
      }

      /* Main initialization function */
      function init() {
        populateData();
        initThemeSwitcher();

        /* Handler for main sections */
        $('.section-header').on('click', function () {
          toggleSection($(this));
        });

        /* Handler for collapsible NPC cards using event delegation */
        $('#npc-container').on('click', '.npc-header', function() {
            const $header = $(this);
            const $content = $header.next('.npc-body');
            $content.toggleClass('expanded');
            $header.find('.arrow').css('transform', $content.hasClass('expanded') ? 'rotate(90deg)' : 'rotate(0deg)');
        });
      }

      $(() => errorCatched(init)());
